arguments.command:
cd /workspace/dev && LD_LIBRARY_PATH=/workspace/native SYNECDOCHE_SITE=/workspace/site PYTHONPATH=/workspace/site python3 - <<'EOF'
import sys, json, io, traceback
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/dev')
import formats, pipeline
disc=[{'class':0,'values':[1600,1400,20,20,20,20],'activation':[100,100,0,0,0,0]} for _ in range(2)]
rel={'id':'r','classes':1,'width':2,'eps':[0,1],'ratio':[0,1],'threshold':[0,1],'mode':'range',
     'packet_limit':10,'idle_us':1000,'discovery':disc,
     'train':[{'class':0,'values':[1600,1400]}],'validation':[{'class':0,'values':[1600,1400]}]}
req={'capacity':{'range':100,'exact':100},'releases':[rel],'blocks':[['install','r']]}
data=json.dumps(req).encode()
try:
    p=formats.read_request(io.BytesIO(data))
except Exception:
    traceback.print_exc(); raise SystemExit
try:
    out=pipeline.execute(p)
    print(json.dumps(out)[:1500])
except Exception:
    traceback.print_exc()
EOF
